import sys
from collections import defaultdict
import heapq

MOD = 10**9 + 7

def dijkstra(graph, start, n):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        current_dist, u = heapq.heappop(pq)
        if current_dist > dist[u]:
            continue
        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))
    return dist

def mst_kruskal(edges, n):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        rootU = find(u)
        rootV = find(v)
        if rootU != rootV:
            if rank[rootU] > rank[rootV]:
                parent[rootV] = rootU
            elif rank[rootU] < rank[rootV]:
                parent[rootU] = rootV
            else:
                parent[rootV] = rootU
                rank[rootU] += 1
            return True
        return False

    edges.sort(key=lambda x: x[2])
    mst_edges = []
    for u, v, weight in edges:
        if union(u, v):
            mst_edges.append((u, v, weight))
            if len(mst_edges) == n - 1:
                break
    return mst_edges

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    N = int(input[index])
    M = int(input[index + 1])
    index += 2
    edges = []
    for _ in range(M):
        X = int(input[index])
        Y = int(input[index + 1])
        Z = int(input[index + 2])
        edges.append((X, Y, Z))
        index += 3

    mst_edges = mst_kruskal(edges, N)
    graph = defaultdict(list)
    for u, v, weight in mst_edges:
        graph[u].append((v, weight))
        graph[v].append((u, weight))

    product = 1
    for i in range(1, N + 1):
        dist = dijkstra(graph, i, N)
        for j in range(i + 1, N + 1):
            min_cut = float('inf')
            for u, v, weight in mst_edges:
                if (dist[u] + weight == dist[j]) or (dist[v] + weight == dist[j]):
                    min_cut = min(min_cut, weight)
            product = (product * min_cut) % MOD

    print(product)

if __name__ == "__main__":
    main()
